# Build output by copying pattern from lower section to upper, with horizontal mirroring
test_input = [
    [9,9,9,9,9,9,9,9,4,9,9,9,9,9,9,9,9,4,9,9,9,9,9,9,9,9],
    [9,9,9,9,9,9,9,9,4,9,9,9,9,9,9,9,9,4,9,9,9,9,9,9,9,9],
    [4,4,4,4,4,4,4,4,4,4,4,4,4,4,4,4,4,4,4,4,4,4,4,4,4,4],
    [9,9,9,9,9,9,9,9,4,8,9,8,9,6,9,8,7,4,9,9,9,9,9,9,9,9],
    [9,9,9,9,9,9,9,9,4,9,9,9,8,8,3,9,9,4,9,9,9,9,9,9,9,9]
]

sep_cols = [8, 17]

# Copy row 3 to row 0, row 4 to row 1, separator to row 2
output = [row[:] for row in test_input]
output[0] = test_input[3][:]
output[1] = test_input[4][:]
output[2] = [4]*26

# Now mirror row 0 and 1 horizontally
def mirror_row(row, sep_cols):
    result = row[:]
    for sc in sep_cols:
        for j in range(len(row)):
            if j not in sep_cols:
                mir = sc * 2 - j
                if mir >= 0 and mir < len(row) and mir not in sep_cols:
                    result[mir] = row[j]
    return result

output[0] = mirror_row(output[0], sep_cols)[1]
for sc in sep_cols:
    for j in range(len(output[0])):
        if j not in sep_cols:
            mir = sc * 2 - j
            if mir >= 0 and mir < len(output[0]) and mir not in sep_cols:
                output[0][mir] = output[0][j]

output[1] = mirror_row(output[1], sep_cols)[1]
for sc in sep_cols:
    for j in range(len(output[1])):
        if j not in sep_cols:
            mir = sc * 2 - j
            if mir >= 0 and mir < len(output[1]) and mir not in sep_cols:
                output[1][mir] = output[1][j]

print(f"After mirroring row 0: {output[0]}")
print(f"After mirroring row 1: {output[1]}")

